// Jinx UI API assumed (Field/Input/Stack/Tag with onRemove) — verify against the installed @jinx-ui/react version.
import { useCallback, useState, type ChangeEvent, type KeyboardEvent } from 'react';
import { Field, Input, Stack, Tag, Text } from '@jinx-ui/react';

type ArticleTagsInputProps = {
  onChange: (tags: string[]) => void;
  label?: string;
  placeholder?: string;
  initialTags?: string[];
};

export default function ArticleTagsInput({
  onChange,
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  initialTags = [],
}: ArticleTagsInputProps) {
  const [tags, setTags] = useState<string[]>(initialTags);
  const [draft, setDraft] = useState('');

  const apply = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange(next);
    },
    [onChange],
  );

  const commitDraft = useCallback(() => {
    const value = draft.trim();
    setDraft('');
    if (!value) return;
    if (tags.some((tag) => tag.toLowerCase() === value.toLowerCase())) return;
    apply([...tags, value]);
  }, [apply, draft, tags]);

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      commitDraft();
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      apply(tags.slice(0, -1));
    }
  };

  return (
    <Stack direction="column" gap="var(--jx-space-2)">
      <Field label={label}>
        <Input
          value={draft}
          placeholder={placeholder}
          onChange={(event: ChangeEvent<HTMLInputElement>) => setDraft(event.target.value)}
          onKeyDown={handleKeyDown}
          onBlur={commitDraft}
        />
      </Field>

      {tags.length > 0 ? (
        <Stack direction="row" wrap gap="var(--jx-space-1)">
          {tags.map((tag) => (
            <Tag
              key={tag}
              onRemove={() => apply(tags.filter((item) => item !== tag))}
              removeLabel={`Удалить тег ${tag}`}
            >
              {tag}
            </Tag>
          ))}
        </Stack>
      ) : (
        <Text tone="muted" size="sm">
          Теги пока не выбраны
        </Text>
      )}
    </Stack>
  );
}

